import{_ as e,c as i,o as s,a3 as o}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"Instalación","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/installation.md","filePath":"es/guide/installation.md","lastUpdated":1787284674000}'),l={name:"es/guide/installation.md"};function n(r,a,t,c,d,p){return s(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h1><p>ClipboxAI está disponible para macOS.</p><h2 id="opciones-de-descarga" tabindex="-1">Opciones de descarga <a class="header-anchor" href="#opciones-de-descarga" aria-label="Permalink to &quot;Opciones de descarga&quot;">​</a></h2><h3 id="mac-app-store-recomendado" tabindex="-1">Mac App Store (recomendado) <a class="header-anchor" href="#mac-app-store-recomendado" aria-label="Permalink to &quot;Mac App Store (recomendado)&quot;">​</a></h3><ul><li><strong>Descargar</strong>: busque <strong>ClipboxAI</strong> en la Mac App Store, o abra el enlace desde la <a href="/es/">página de inicio</a>.</li><li>La versión de la Mac App Store ofrece actualizaciones automáticas e integración perfecta con macOS.</li></ul><blockquote><p><s>Si aún no hay un enlace de la Mac App Store disponible, utilice la compilación de GitHub Releases que aparece a continuación.</s></p></blockquote><h3 id="github-releases-alternativa-no-disponible-por-ahora" tabindex="-1"><s>GitHub Releases (alternativa)</s> (no disponible por ahora) <a class="header-anchor" href="#github-releases-alternativa-no-disponible-por-ahora" aria-label="Permalink to &quot;~~GitHub Releases (alternativa)~~ (no disponible por ahora)&quot;">​</a></h3><p><s>Puede descargar la última compilación directamente desde <a href="https://github.com/clipboxAI" target="_blank" rel="noreferrer">GitHub Releases</a>. Tenga en cuenta que esta versión no recibe actualizaciones automáticas.</s></p><h2 id="pasos-de-instalacion" tabindex="-1">Pasos de instalación <a class="header-anchor" href="#pasos-de-instalacion" aria-label="Permalink to &quot;Pasos de instalación&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>Abra el enlace de descarga anterior o busque &quot;ClipboxAI&quot; en la Mac App Store.</li><li>Haga clic en <strong>Obtener</strong> para descargar la aplicación.</li><li>La aplicación se instala automáticamente — ábrala desde <strong>Aplicaciones</strong> o <strong>Launchpad</strong>.</li></ol><h3 id="github-releases" tabindex="-1"><s>GitHub Releases</s> <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;~~GitHub Releases~~&quot;">​</a></h3><ol><li><s>Descargue el último <code>.dmg</code> desde la página de Releases.</s></li><li><s>Haga doble clic en el <code>.dmg</code> descargado para abrirlo.</s></li><li><s>Arrastre el icono <code>ClipboxAI.app</code> a su carpeta <strong>Aplicaciones</strong>.</s></li><li><s>Expulse la imagen montada y abra la aplicación desde <strong>Aplicaciones</strong>.</s></li></ol><p>Si macOS impide abrir la aplicación (Gatekeeper), abra <strong>Configuración del sistema → Privacidad y seguridad</strong> y haga clic en <strong>Abrir de todos modos</strong>, o haga clic derecho en la aplicación y elija <strong>Abrir</strong>.</p><h2 id="primer-inicio" tabindex="-1">Primer inicio <a class="header-anchor" href="#primer-inicio" aria-label="Permalink to &quot;Primer inicio&quot;">​</a></h2><p>En el primer inicio, ClipboxAI le guía a través de una breve configuración:</p><ul><li><strong>Habilitar el elemento de la barra de menú</strong> para que la aplicación resida en su barra de menú.</li><li><strong>Conceder permisos</strong> que necesita para supervisar el portapapeles en segundo plano (consulte <a href="/es/guide/permissions.html">Permisos</a>).</li><li><em>(Opcional)</em> <strong>Conectar un proveedor de IA en la nube</strong> en <strong>Ajustes → IA</strong> si desea acciones de IA.</li></ul><p>Conceda los permisos cuando se lo soliciten. Puede cambiarlos en cualquier momento en <strong>Configuración del sistema → Privacidad y seguridad</strong>.</p><h2 id="actualizaciones" tabindex="-1">Actualizaciones <a class="header-anchor" href="#actualizaciones" aria-label="Permalink to &quot;Actualizaciones&quot;">​</a></h2><ul><li><strong>Versión de la Mac App Store</strong>: se actualiza automáticamente mediante la App Store.</li><li><s><strong>Versión de GitHub Releases</strong>: descargue la versión más reciente y reemplace la aplicación en <code>Applications</code>.</s></li></ul><h2 id="desinstalacion" tabindex="-1">Desinstalación <a class="header-anchor" href="#desinstalacion" aria-label="Permalink to &quot;Desinstalación&quot;">​</a></h2><p>Para eliminar ClipboxAI:</p><ol><li>Salga de la aplicación.</li><li>Arrastre <code>ClipboxAI.app</code> desde <code>Applications</code> a la Papelera.</li><li>(Opcional) Elimine los datos locales:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Application</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Scripts/com.w3cub.clipboard</span></span></code></pre></div><h2 id="requisitos-del-sistema" tabindex="-1">Requisitos del sistema <a class="header-anchor" href="#requisitos-del-sistema" aria-label="Permalink to &quot;Requisitos del sistema&quot;">​</a></h2><ul><li><strong>macOS</strong>: Sonoma (14) o posterior</li><li><strong>CPU</strong>: Apple Silicon (serie M) o Intel (64 bits)</li><li><strong>Memoria</strong>: 4 GB mínimo, 8 GB recomendado</li><li><strong>Almacenamiento</strong>: ~50 MB</li></ul><h2 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h2><p>Si encuentra problemas durante la instalación:</p><ul><li><strong>macOS bloquea la aplicación</strong>: abra <strong>Configuración del sistema → Privacidad y seguridad</strong> y haga clic en <strong>Abrir de todos modos</strong>.</li><li><strong>Aviso de notarización</strong>: descargue una compilación firmada y notarizada desde la Mac App Store.</li></ul><p>Para obtener más ayuda, consulte la <a href="/es/guide/troubleshooting.html">guía de solución de problemas</a>.</p>`,30)])])}const g=e(l,[["render",n]]);export{h as __pageData,g as default};
